mapper.update:
update clazz
name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId}, subject = #{subject}
WHERE id = #{id}

mapper.select:
select c.*  from clazz c


        c.name = #{name}


        and c.begin_date between #{begin} and #{end}
        and c.end_date between #{begin} and #{end}


order by c.update_time desc
